dataSet.query:
ВЫБРАТЬ НАЧАЛОПЕРИОДА(Трафик.Период, МЕСЯЦ) КАК Период, Трафик.ДилерскийЦентр, Трафик.ТипТрафика, РЛ.IDK ПОМЕСТИТЬ Трафик ИЗ РегистрСведений.Renault_Трафик КАК Трафик ЛЕВОЕ СОЕДИНЕНИЕ Документ.Renault_РабочийЛист КАК РЛ ПО (РЛ.IDТрафика = Трафик.Идентификатор) И (РЛ.Отдел.КлассификацияRenault = ЗНАЧЕНИЕ(Перечисление.CRM_КлассификацияОтделов.ОтделПродажАвтомобилей) ИЛИ РЛ.Отдел.КлассификацияRenault = ЗНАЧЕНИЕ(Перечисление.CRM_КлассификацияОтделов.ОтделКорпоративныхПродаж)) ГДЕ Трафик.Период >= &ДатаНачала И Трафик.Период <= &ДатаОкончания И (Трафик.Отдел.КлассификацияRenault = ЗНАЧЕНИЕ(Перечисление.CRM_КлассификацияОтделов.ОтделПродажАвтомобилей) ИЛИ Трафик.Отдел.КлассификацияRenault = ЗНАЧЕНИЕ(Перечисление.CRM_КлассификацияОтделов.ОтделКорпоративныхПродаж)) ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ Воронка.ДилерскийЦентр, Воронка.IDK, МАКСИМУМ(ВЫБОР КОГДА Воронка.ЭтапПродаж = ЗНАЧЕНИЕ(Справочник.CRM_ЭтапыПродаж.КоммерческоеПредложение) ТОГДА 1 ИНАЧЕ 0 КОНЕЦ) КАК КП, МАКСИМУМ(ВЫБОР КОГДА Воронка.ЭтапПродаж = ЗНАЧЕНИЕ(Справочник.CRM_ЭтапыПродаж.ТестДрайв) ТОГДА 1 ИНАЧЕ 0 КОНЕЦ) КАК ТД, МАКСИМУМ(ВЫБОР КОГДА Воронка.ЭтапПродаж = ЗНАЧЕНИЕ(Справочник.CRM_ЭтапыПродаж.ВыдачаАвтомобиля) ТОГДА 1 ИНАЧЕ 0 КОНЕЦ) КАК Выдача, МАКСИМУМ(ВЫБОР КОГДА Воронка.ЭтапПродаж = ЗНАЧЕНИЕ(Справочник.CRM_ЭтапыПродаж.ДКП) ТОГДА 1 ИНАЧЕ 0 КОНЕЦ) КАК ДКП, МАКСИМУМ(ВЫБОР КОГДА Воронка.ЭтапПродаж = ЗНАЧЕНИЕ(Справочник.CRM_ЭтапыПродаж.ПосещениеАвтосалона) ТОГДА 1 ИНАЧЕ 0 КОНЕЦ) КАК Посещение ПОМЕСТИТЬ Воронка ИЗ РегистрСведений.Renault_СтатистикаВыполненияЭтаповПродаж КАК Воронка ГДЕ ДатаВыполнения >= &ДатаНачала И ДатаВыполнения <= &ДатаОкончания
СГРУППИРОВАТЬ ПО Воронка.ДилерскийЦентр, Воронка.IDK ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ Трафик.Период, Трафик.ДилерскийЦентр, Трафик.ДилерскийЦентр.DMD КАК BIR, ВЫБОР КОГДА Трафик.ТипТрафика = ЗНАЧЕНИЕ(Справочник.CRM_ТипТрафика.ПосещениеАвтосалона) ИЛИ ЕСТЬNULL(Воронка.Посещение, 0) = 1 ТОГДА 1 ИНАЧЕ 0 КОНЕЦ КАК Визиты, ВЫБОР КОГДА (Трафик.ТипТрафика = ЗНАЧЕНИЕ(Справочник.CRM_ТипТрафика.ПосещениеАвтосалона) ИЛИ ЕСТЬNULL(Воронка.Посещение, 0) = 1) И ЕСТЬNULL(Воронка.Выдача, 0) = 1 ТОГДА 1 ИНАЧЕ 0 КОНЕЦ КАК ВыдачиСВизитов, ВЫБОР КОГДА (Трафик.ТипТрафика = ЗНАЧЕНИЕ(Справочник.CRM_ТипТрафика.ПосещениеАвтосалона) ИЛИ ЕСТЬNULL(Воронка.Посещение, 0) = 1) И ЕСТЬNULL(Воронка.ДКП, 0) = 1 ТОГДА 1 ИНАЧЕ 0 КОНЕЦ КАК ДКПСВизитов, ВЫБОР КОГДА (Трафик.ТипТрафика = ЗНАЧЕНИЕ(Справочник.CRM_ТипТрафика.ПосещениеАвтосалона) ИЛИ ЕСТЬNULL(Воронка.Посещение, 0) = 1) И ЕСТЬNULL(Воронка.КП, 0) = 1 ТОГДА 1 ИНАЧЕ 0 КОНЕЦ КАК КПСВизитов, ВЫБОР КОГДА (Трафик.ТипТрафика = ЗНАЧЕНИЕ(Справочник.CRM_ТипТрафика.ПосещениеАвтосалона) ИЛИ ЕСТЬNULL(Воронка.Посещение, 0) = 1) И ЕСТЬNULL(Воронка.ТД, 0) = 1 ТОГДА 1 ИНАЧЕ 0 КОНЕЦ КАК ТДСВизитов, ВЫБОР КОГДА Трафик.ТипТрафика = ЗНАЧЕНИЕ(Справочник.CRM_ТипТрафика.ЛидRenault) ТОГДА 1 ИНАЧЕ 0 КОНЕЦ КАК Лиды, ВЫБОР КОГДА Трафик.ТипТрафика = ЗНАЧЕНИЕ(Справочник.CRM_ТипТрафика.Звонок) ТОГДА 1 ИНАЧЕ 0 КОНЕЦ КАК Звонки, ЕСТЬNULL(Воронка.ТД, 0) КАК ТестДрайвы, ЕСТЬNULL(Воронка.КП, 0) КАК КП, ЕСТЬNULL(Воронка.ДКП, 0) КАК ДКП, ЕСТЬNULL(Воронка.Выдача, 0) КАК Выдачи, ВЫБОР КОГДА Трафик.ТипТрафика = ЗНАЧЕНИЕ(Справочник.CRM_ТипТрафика.ЛидRenault) И ЕСТЬNULL(Воронка.Посещение, 0) = 1 ТОГДА 1 ИНАЧЕ 0 КОНЕЦ КАК ВизитыСЛидов, ВЫБОР КОГДА Трафик.ТипТрафика = ЗНАЧЕНИЕ(Справочник.CRM_ТипТрафика.Звонок) И ЕСТЬNULL(Воронка.Посещение, 0) = 1 ТОГДА 1 ИНАЧЕ 0 КОНЕЦ КАК ВизитыСоЗвонков, ВЫБОР КОГДА ЕСТЬNULL(Воронка.ТД, 0) = 1 И ЕСТЬNULL(Воронка.КП, 0) = 1 ТОГДА 1 ИНАЧЕ 0 КОНЕЦ КАК КПСТД, ВЫБОР КОГДА ЕСТЬNULL(Воронка.КП, 0) = 1 И ЕСТЬNULL(Воронка.ДКП, 0) = 1 ТОГДА 1 ИНАЧЕ 0 КОНЕЦ КАК ДКПСКП, ВЫБОР КОГДА ЕСТЬNULL(Воронка.ДКП, 0) = 1 И ЕСТЬNULL(Воронка.Выдача, 0) = 1 ТОГДА 1 ИНАЧЕ 0 КОНЕЦ КАК ВыдачиСДКП, 1 КАК ГруппаВсегоЗвонки, 0 КАК ВизитыСЛидовПроцент, 0 КАК ВизитыСоЗвонковПроцент ИЗ Трафик КАК Трафик ЛЕВОЕ СОЕДИНЕНИЕ Воронка КАК Воронка ПО (Воронка.ДилерскийЦентр = Трафик.ДилерскийЦентр) И (Воронка.IDK = Трафик.IDK)
